/**
 * The Fallen Silver Drift — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { SILVER_DRIFT_RESCUE_TEMPLATE } from '../silver-drift-rescue';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Fallen Silver Drift — template structure", () => {
  it('carries its identity', () => {
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.id).toBe('encounter.town.silver_drift_rescue');
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.reach).toBe('stone');
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.rarityTier).toBe(2);
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.steps).toHaveLength(3);
  });

  it('step 0 deals the authored hand', () => {
    const step = SILVER_DRIFT_RESCUE_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['drift.carry_faint_knocking', 'drift.remember_lost_tunnels']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['matter', 'mind']);
  });

  it('step 1 deals the authored hand', () => {
    const step = SILVER_DRIFT_RESCUE_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['drift.harden_green_timber', 'drift.still_loose_rock']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['life', 'order']);
  });

  it('step 2 deals the authored hand', () => {
    const step = SILVER_DRIFT_RESCUE_TEMPLATE.steps[2];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['drift.stir_dead_air', 'drift.rouse_weary_bodies']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['chaos', 'life']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.settings).toEqual(['rural']);
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.locationSubtypes).toEqual(expandSettings(['rural']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.consequenceDraw).toEqual(['condition', 'membership']);
    expect(SILVER_DRIFT_RESCUE_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.silver_drift_rescue',
          reach: 'stone',
          rarityTier: 2,
        }),
        SILVER_DRIFT_RESCUE_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
